// Unmodified source-host transactions, including complete adapter replies and calls.
import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
const cases=[];
const specs={extended:{method:'MixerExtended',tool:'mixer_extended',args:{trackRef:'track:track-1',trackActivator:false,crossfader:-0.5,crossfadeAssign:0,panningMode:1,panningLeft:-0.25,panningRight:0.25}},chain:{method:'ChainMixer',tool:'chain_mixer',args:{chainRef:'chain:rack-1:0',volume:0.5,pan:-0.5,sends:[0.25],chainActivator:false}},routing:{method:'DeviceIo',tool:'device_io',args:{action:'routing',deviceRef:'device:utility-1',routingType:'Main',routingChannel:'1/2'}},sidechain:{method:'DeviceIo',tool:'device_io',args:{action:'sidechain',deviceRef:'device:utility-1',routingType:'Ext. In'}}};
function clean(value){if(value===undefined)return null;value=structuredClone(value);if(value?.result?.content?.[0]?.text)try{value.result.content[0].text=JSON.parse(value.result.content[0].text)}catch{}function walk(v,key){if(typeof v==='string'&&/^(mixerext|chainmix|devio)_/.test(v))return '$transaction';if(key==='expiresAt'&&v!==0)return '$time';if(Array.isArray(v))return v.map(w=>walk(w));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,w])=>[k,walk(w,k)]));return v;}return walk(value);}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
async function make(kind,scenario,args=specs[kind].args,previewOnly=false){const spec=specs[kind],sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,after=false;
 const track=sim.state.tracks[0],device=track.devices[0];device.kind='rack';device.canHaveChains=true;device.chains=[{ref:'chain:rack-1:0',parentRef:'device:utility-1',objectIdentity:'simulator:chain:rack-1:0',index:0,name:'Chain 1',mute:false,solo:false,devices:[],mixer:{volume:1,pan:0,sends:[0.5],volumeRef:'parameter:chain:0:volume',panningRef:'parameter:chain:0:panning',sendRefs:['parameter:chain:0:sends:0'],chainActivatorRef:'parameter:chain:0:activator',mixerIdentity:'simulator:chain-mixer:0'}}];device.deviceIo={routingType:'Ext. In',routingChannel:'1'};device.sidechainRoutingType='None';
 const object=kind==='extended'?track:kind==='chain'?device.chains[0]:device;
 if(scenario==='missing-identity')delete object.objectIdentity;if(scenario==='missing-mixer')delete object.mixer;if(scenario==='missing-mixer-identity'&&object.mixer)delete object.mixer.mixerIdentity;if(scenario==='missing-io')delete device.deviceIo;if(scenario==='missing-sidechain')delete device.sidechainRoutingType;
 function status(){const s=sim.status();if(scenario==='disconnected')s.connected=false;if(scenario==='no-capability')s.capabilities=[];if(scenario==='no-operation')s.operations=[];return s;}
 function readFault(){if(!fired&&(fault.endsWith('current-read')||fault.endsWith('-read')&&after)){fired=true;throw Error('injected authoritative read failure');}}
 async function capture(method,args,ctx,work){const row={method,args:clean(args),context:clean(context(ctx))};calls.push(row);try{const value=await work();row.result=clean(value);return value}catch(error){row.error={message:error.message,kind:error instanceof LiveMutationNotDispatchedError?'not-dispatched':'error'};throw error}}
 function invoke(i,c){const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}if(!fired&&fault.endsWith('null')){fired=true;return null}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));after=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}if(!fired&&fault==='apply-postcondition'){fired=true;if(kind==='extended')track.mixer.crossfader=1;if(kind==='chain')object.mixer.volume=1;if(kind==='routing')device.deviceIo.routingType='Other';if(kind==='sidechain')device.sidechainRoutingType='Other'}return result;}
 const adapter={status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>sim.invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),refreshStatusAsync:c=>capture('status',null,c,()=>status()),snapshotAsync:(c,r)=>capture('snapshot',r??null,c,()=>{readFault();return sim.snapshotAsync(c,r)}),discoverAsync:(r,c)=>capture('discover',r,c,()=>{readFault();return sim.discoverAsync(r,c)}),getAsync:(r,c)=>capture('get',r,c,()=>{readFault();return sim.get(r)}),invokeAsync:(i,c)=>capture('invoke',i,c,()=>invoke(i,c))};
 const host=new McpHost(adapter),steps=[];let txid;
 async function step(action,p,extra={}){const before=calls.length,input={action,args:clean(p),status:status(),...extra};let result;try{const signal=new AbortController();if(extra.abort)signal.abort();if(action==='undo')result=await host.liveUndoAsync(1,{...p,transactionId:txid},signal.signal);else result=await host['live'+spec.method+(action==='preview'?'Preview':'Apply')+'Async'](1,action==='preview'?p:{...p,transactionId:txid},signal.signal)}catch(error){result={throw:error.message}}if(action==='preview')try{txid=JSON.parse(result.result.content[0].text).transactionId}catch{}steps.push({...input,result:clean(result),record:clean(txid?host.clipLifecycleTransactions.get(txid):undefined),calls:calls.slice(before)})}
 await step('preview',args);if(txid&&!previewOnly){const t=host.clipLifecycleTransactions.get(txid);if(scenario==='expire')t.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity')object.objectIdentity='manual';if(scenario==='mixer-identity'&&object.mixer)object.mixer.mixerIdentity='manual';if(scenario==='state'){if(kind==='extended')track.mixer.crossfadeAssign=2;if(kind==='chain')object.mixer.sends=[0];if(kind==='routing')device.deviceIo.routingType='Other';if(kind==='sidechain')device.sidechainRoutingType='Other'}
 if(scenario.startsWith('apply-'))fault=scenario;for(const[index,key]of['apply-key','other-key','apply-key'].entries())await step('apply',{confirmation:'apply',idempotencyKey:key},{...(scenario==='expire'&&index===0?{expire:true}:{}),...(scenario==='apply-preabort'?{abort:true}:{})});fault='';fired=false;after=false;
 if(scenario==='undo-epoch')sim.reconnect();if(scenario==='undo-identity')object.objectIdentity='manual';if(scenario==='undo-mixer-identity'&&object.mixer)object.mixer.mixerIdentity='manual';if(scenario==='undo-state'){if(kind==='extended')track.mixer.crossfader=1;if(kind==='chain')object.mixer.volume=1;if(kind==='routing')device.deviceIo.routingChannel='Other';if(kind==='sidechain')device.sidechainRoutingType='Other'}
 if(scenario.startsWith('undo-')&&!['undo-epoch','undo-identity','undo-mixer-identity','undo-state'].includes(scenario))fault=scenario;for(const key of ['undo-key','other-undo-key','undo-key'])await step('undo',{confirmation:'undo',idempotencyKey:key});}
 cases.push({label:kind+' '+scenario,tool:spec.tool,steps});}
const scenarios=['normal','expire','epoch','identity','mixer-identity','state','missing-identity','missing-mixer','missing-mixer-identity','missing-io','missing-sidechain','disconnected','no-capability','no-operation','apply-before','apply-after','apply-refusal','apply-no-effect','apply-null','apply-read','apply-current-read','apply-preabort','apply-postcondition','undo-before','undo-after','undo-refusal','undo-no-effect','undo-null','undo-read','undo-current-read','undo-epoch','undo-identity','undo-mixer-identity','undo-state'];
for(const kind of Object.keys(specs)){for(const scenario of scenarios)await make(kind,scenario);const valid=specs[kind].args;for(const args of [null,[],{},false,0,'x',{...valid,extra:1}])await make(kind,'invalid '+JSON.stringify(args),args,true);for(const key of Object.keys(valid)){const omit={...valid};delete omit[key];await make(kind,'omitted '+key,omit,true);for(const value of [null,[],{},false,true,-1,0,0.5,2,9,'','a'.repeat(257)])await make(kind,'invalid '+key+' '+JSON.stringify(value),{...valid,[key]:value},true)}}
fs.writeFileSync(new URL('host-extended-mixer-oracle.json',import.meta.url),JSON.stringify({cases}));console.log({cases:cases.length,steps:cases.reduce((n,c)=>n+c.steps.length,0)});
